<script lang="ts">
 import {onMount} from 'svelte';
 import PageHeader from '../components/PageHeader.svelte';
 import {api,type Hero,type Result} from '../types';
 import type {Item} from '../lib/build-types';
 import {decodeBuild,encodeBuild,type WorkshopBuild,type WorkshopCategory,type WorkshopItem} from '../lib/hero-build-codec';
 let heroes=$state<Hero[]>([]),items=$state<Item[]>([]),heroId=$state(0),name=$state(''),description=$state(''),categories=$state<WorkshopCategory[]>([]),code=$state(''),generated=$state(''),message=$state(''),error=$state(''),loading=$state(true),hasSavedDraft=$state(false);
 const draftKey='deadlook.buildWorkshop.draft.v1';
 const slots=[{key:'weapon',label:'Weapon'},{key:'vitality',label:'Vitality'},{key:'spirit',label:'Spirit'}];
 const itemsBySlot=(slot:string)=>items.filter(i=>i.type==='upgrade'&&i.item_slot_type===slot).sort((a,b)=>a.name.localeCompare(b.name));
 function addCategory(){categories=[...categories,{name:'New category',description:'',width:2,height:3,items:[]}];}
 function categorySlot(name:string){const lower=name.toLowerCase();return lower.includes('vital')?'vitality':lower.includes('spirit')?'spirit':'weapon';}
 function addItem(c:number){const slot=categorySlot(categories[c]?.name||'');categories=categories.map((cat,i)=>i===c?{...cat,items:[...cat.items,{itemId:itemsBySlot(slot)[0]?.id||0,annotation:''}]}:cat);}
 function patchItem(c:number,r:number,patch:Partial<WorkshopItem>){categories=categories.map((cat,i)=>i===c?{...cat,items:cat.items.map((it,j)=>j===r?{...it,...patch}:it)}:cat);}
 function move(c:number,r:number,delta:number){const rows=[...categories[c].items],to=r+delta;if(to<0||to>=rows.length)return;[rows[r],rows[to]]=[rows[to],rows[r]];categories=categories.map((cat,i)=>i===c?{...cat,items:rows}:cat);}
 function remove(c:number,r:number){categories=categories.map((cat,i)=>i===c?{...cat,items:cat.items.filter((_,j)=>j!==r)}:cat);}
 async function generate(){error='';generated='';if(!heroId){error='Choose a hero first.';return false;}if(!name.trim()){error='Enter a build name first.';return false;}if(categories.some(c=>c.items.some(i=>!i.itemId))){error='Choose an item for each added row, or remove the empty row.';return false;}try{generated=await encodeBuild({heroId,name:name.trim(),description,categories});message='Clipboard build code generated.';return true;}catch(e){error=(e as Error).message;return false;}}
 async function copy(){if(!await generate())return;try{await navigator.clipboard.writeText(generated);message='Build code copied to clipboard.';}catch{message='Clipboard permission unavailable. Select and copy the generated code below.';}}
 async function importCode(){error='';try{const b:WorkshopBuild=await decodeBuild(code);heroId=b.heroId;name=b.name;description=b.description;categories=b.categories;message='Build imported and ready to edit.';}catch(e){error=(e as Error).message;}}
 async function paste(){try{code=await navigator.clipboard.readText();await importCode();}catch(e){error=(e as Error).message||'Clipboard read unavailable. Paste the code into the import field.';}}
 function saveDraft(){try{localStorage.setItem(draftKey,JSON.stringify({heroId,name,description,categories}));hasSavedDraft=true;message='Draft saved in this browser.';error='';}catch{error='Could not save a local draft. Check browser storage settings.';}}
 function restoreDraft(){try{const raw=localStorage.getItem(draftKey);if(!raw)throw new Error('No saved draft found in this browser.');const draft=JSON.parse(raw) as Partial<WorkshopBuild>;if(!Number.isInteger(draft.heroId)||!Array.isArray(draft.categories))throw new Error('Saved draft is invalid.');heroId=draft.heroId!;name=typeof draft.name==='string'?draft.name:'';description=typeof draft.description==='string'?draft.description:'';categories=draft.categories;message='Draft restored from this browser.';error='';}catch(e){error=(e as Error).message;}}
 onMount(async()=>{hasSavedDraft=!!localStorage.getItem(draftKey);try{const [h,it]=await Promise.all([api<Result<Hero[]>>('/api/heroes'),api<Result<Item[]>>('/api/finder/items')]);heroes=h.data.filter(x=>x.playable!==false).sort((a,b)=>a.name.localeCompare(b.name));items=it.data;heroId=heroes[0]?.id||0;categories=[{name:'Weapon',description:'',width:2,height:3,items:[]},{name:'Vitality',description:'',width:2,height:3,items:[]},{name:'Spirit',description:'',width:2,height:3,items:[]}];}catch(e){error=(e as Error).message;}finally{loading=false;}});
</script>
<svelte:head><title>Build Workshop · Deadlook</title></svelte:head>
<PageHeader eyebrow="BUILD TOOLS" title="Build Workshop" description="Create and edit an in-game clipboard build code locally in your browser."/>
<div class="page-body"><div class="container-xl">
 <div class="alert alert-info" role="note">Create item categories and copy a clipboard build code to paste into Deadlock’s build UI; save or publish it in game. This page works locally in your browser and never connects to Steam or sends your draft to a server. Imported ability-order data is retained, but editing ability point order is not yet supported. Game client compatibility can vary.</div>
 {#if error}<div class="alert alert-danger" role="alert">{error}</div>{/if}
 <section class="card mb-4"><div class="card-header"><h2 class="card-title">Build details</h2><div class="ms-auto d-flex gap-2"><button class="btn btn-sm btn-outline-primary" onclick={saveDraft}>Save draft</button><button class="btn btn-sm btn-outline-secondary" onclick={restoreDraft} disabled={!hasSavedDraft}>Restore draft</button></div></div><div class="card-body"><div class="row g-3"><div class="col-12 col-md-4"><label class="form-label" for="workshop-hero">Hero</label><select class="form-select" id="workshop-hero" bind:value={heroId} disabled={loading}>{#each heroes as hero}<option value={hero.id}>{hero.name}</option>{/each}</select></div><div class="col-12 col-md-8"><label class="form-label" for="workshop-name">Build name</label><input class="form-control" id="workshop-name" bind:value={name} maxlength="128"/></div><div class="col-12"><label class="form-label" for="workshop-description">Description</label><textarea class="form-control" id="workshop-description" bind:value={description} rows="2" maxlength="2048"></textarea></div></div></div></section>
 <section class="card mb-4"><div class="card-header"><h2 class="card-title">Item categories</h2><button class="btn btn-outline-primary ms-auto" onclick={addCategory}>Add category</button></div><div class="card-body">{#if !categories.length}<p class="text-secondary">No categories yet. Add a category to start building.</p>{/if}{#each categories as category,c}<fieldset class="border rounded p-3 mb-3"><legend class="float-none w-auto px-2 fs-4">Category {c+1}</legend><div class="row g-3 mb-3"><div class="col-md-4"><label class="form-label" for={'cat-name-'+c}>Category name</label><input class="form-control" id={'cat-name-'+c} value={category.name} oninput={e=>categories=categories.map((x,i)=>i===c?{...x,name:e.currentTarget.value}:x)}/></div><div class="col-md-6"><label class="form-label" for={'cat-desc-'+c}>Description</label><input class="form-control" id={'cat-desc-'+c} value={category.description} oninput={e=>categories=categories.map((x,i)=>i===c?{...x,description:e.currentTarget.value}:x)}/></div><div class="col-md-2"><button class="btn btn-outline-danger mt-4" onclick={()=>categories=categories.filter((_,i)=>i!==c)}>Remove category</button></div></div><label class="form-check mb-3"><input class="form-check-input" type="checkbox" checked={category.optional||false} onchange={e=>categories=categories.map((x,i)=>i===c?{...x,optional:e.currentTarget.checked}:x)}/><span class="form-check-label">Optional category</span></label>{#each category.items as row,r}<div class="row g-2 align-items-end mb-3"><div class="col-12 col-md-3"><label class="form-label" for={'slot-'+c+'-'+r}>Item category</label><select class="form-select" id={'slot-'+c+'-'+r} value={items.find(it=>it.id===row.itemId)?.item_slot_type||'weapon'} onchange={e=>patchItem(c,r,{itemId:itemsBySlot(e.currentTarget.value)[0]?.id||0})}>{#each slots as slot}<option value={slot.key}>{slot.label}</option>{/each}</select></div><div class="col-12 col-md-3"><label class="form-label" for={'item-'+c+'-'+r}>Item</label><select class="form-select" id={'item-'+c+'-'+r} value={row.itemId} onchange={e=>patchItem(c,r,{itemId:Number(e.currentTarget.value)})}>{#each itemsBySlot(items.find(it=>it.id===row.itemId)?.item_slot_type||'weapon') as item}<option value={item.id}>{item.name}</option>{/each}</select></div><div class="col-12 col-md-4"><label class="form-label" for={'note-'+c+'-'+r}>Annotation</label><input class="form-control" id={'note-'+c+'-'+r} value={row.annotation} oninput={e=>patchItem(c,r,{annotation:e.currentTarget.value})}/></div><div class="col-12 col-md-2 d-flex gap-1"><button aria-label="Move item up" class="btn btn-outline-secondary" disabled={r===0} onclick={()=>move(c,r,-1)}>↑</button><button aria-label="Move item down" class="btn btn-outline-secondary" disabled={r===category.items.length-1} onclick={()=>move(c,r,1)}>↓</button><button aria-label="Remove item" class="btn btn-outline-danger" onclick={()=>remove(c,r)}>×</button></div></div>{/each}<button class="btn btn-outline-primary" onclick={()=>addItem(c)} disabled={!itemsBySlot(categorySlot(category.name)).length}>Add item</button></fieldset>{/each}</div></section>
 <section class="card mb-4"><div class="card-header"><h2 class="card-title">Import or paste a build code</h2></div><div class="card-body"><label for="build-import" class="form-label">In-game clipboard build code</label><textarea id="build-import" class="form-control font-monospace mb-3" rows="4" bind:value={code}></textarea><button class="btn btn-outline-primary me-2" onclick={paste}>Paste from clipboard</button><button class="btn btn-outline-primary" onclick={importCode}>Import code</button></div></section>
 <section class="card"><div class="card-header"><h2 class="card-title">Generate in-game clipboard build code</h2><button class="btn btn-primary ms-auto" onclick={copy}>Generate &amp; copy</button></div><div class="card-body">{#if message}<p role="status" class="text-secondary">{message}</p>{/if}<label for="build-output" class="form-label">Generated code</label><textarea id="build-output" class="form-control font-monospace" rows="4" bind:value={generated} readonly></textarea><p class="text-secondary small mt-3 mb-0">Paste this code into Deadlock’s build UI, then save or publish it in game. Compatibility may vary by client version.</p></div></section>
</div></div>
